import React from "react";
import { FaTag, FaChevronLeft } from "react-icons/fa";
import NameEntityForm from "./NameEntityFormComponent";
import withRouter from "./withRouter";

// داده‌ی نمونه
const SAMPLE_BRANDS = {
  1: "سامسونگ_SAMSUNG",
  2: "الجی_LG",
  3: "جنرال الکتریک_GE",
};

// صفحه‌ی مستقل «ویرایش برند دستگاه»
class BrandEditPage extends React.Component {
  constructor(props) {
    super(props);

    const { id } = props.params;

    this.state = {
      initialName: SAMPLE_BRANDS[id] || "",
    };

    this.handleBack = this.handleBack.bind(this);
    this.handleUpdate = this.handleUpdate.bind(this);
  }

  handleBack() {
    this.props.navigate("/brands");
  }

  handleUpdate(name) {
    const trimmed = name.trim();

    if (!trimmed) return;

    const { id } = this.props.params;
    const token = localStorage.getItem("token");

    fetch("https://iranaserviceapp.ir/test/api/add-brand", {
      method: "POST",

      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },

      body: JSON.stringify({
        brand_id: id,
        name: trimmed,
      }),
    })
      .then((response) => response.json())

      .then((data) => {
        console.log("پاسخ API:", data);

        // بعد از ویرایش موفق
        this.props.navigate("/brands");
      })

      .catch((error) => {
        console.error("خطا در ویرایش برند:", error);
      });
  }

  render() {
    const { initialName } = this.state;

    return (
      <div>
        <button
          type="button"
          onClick={this.handleBack}
          className="btn btn-light rounded-circle border p-2 d-flex align-items-center justify-content-center position-absolute"
          style={{
            width: 36,
            height: 36,
            top: 16,
            right: 16,
            zIndex: 1,
          }}
        >
          <FaChevronLeft size={14} />
        </button>

        <NameEntityForm
          title="ویرایش برند دستگاه"
          fieldLabel="نام"
          icon={<FaTag className="text-secondary" size={18} />}
          initialValue={initialName}
          submitLabel="ذخیره تغییرات"
          onSubmit={this.handleUpdate}
        />
      </div>
    );
  }
}

export default withRouter(BrandEditPage);
